sh -c 'lola='lola'; net='/home/michael/RustroverProjects/masters-thesis/evaluation/results/calibration/convert/bb483e66209d94a18315072298335840d2777ad1781862490be74463e58d404a.lola'; unk=0
chk() {
  out=$("$lola" "$net" "--formula=$1" --quiet --json=/dev/stdout); rc=$?
  printf '%s\n' "$out"
  [ "$rc" -eq 0 ] || exit "$rc"
  case "$out" in
    *'"result": true'*|*'"result":true'*) res=true;;
    *'"result": false'*|*'"result":false'*) res=false;;
    *) res=other;;
  esac
  if [ "$res" = "$2" ]; then echo "PETRIVET_ANSWER $2"; exit 0; fi
  [ "$res" = other ] && unk=1
